/**
 * @param {number} n
 * @return {boolean}
 */
var checkDivisibility = function(n) {
    let x = n;
    let sum = 0;
    let mult = 1;

    while (x !== 0) {
        const rem = x % 10;

        sum += rem;
        mult *= rem;

        x = Math.floor(x / 10);
    }

    return n % (sum + mult) === 0;
};
